//! Builder of a 0.0.13-format **SQLite** index, for the importer's tests (`--features import-sqlite`).
//!
//! The schema is the one 0.0.4-0.0.13 created (STRICT tables, the three indexes), written here as data:
//! the store crate no longer contains it. The rows are deterministic (fixed digests, a fixed
//! generation, ids with gaps and the two streams interleaved) so that the API's answers over the imported
//! data can be compared with answers recorded from a real 0.0.13 `api` binary serving this same file
//! (`tests/golden/`, regenerated by `scripts/golden-from-0.0.13.sh`).

use std::path::Path;

use rusqlite::{Connection, params};

use crate::{Fixture, ag, consumed, gate_a, gate_b, minted, platform_updated, seal, sealed};

/// The generation of the fixture index (the live testnet index's looks the same: 12 hex digits).
pub const GENERATION: &str = "e32e37afbbe9";

/// The 0.0.13 `SCHEMA` (crates/store/src/lib.rs at v0.0.13), verbatim.
pub const OLD_SCHEMA: &str = "
CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS cursors (stream TEXT PRIMARY KEY, cursor TEXT) STRICT;
CREATE TABLE IF NOT EXISTS events (
  id INTEGER PRIMARY KEY,
  stream TEXT NOT NULL,
  tx_digest TEXT NOT NULL,
  event_index INTEGER NOT NULL,
  checkpoint INTEGER,
  sender TEXT NOT NULL,
  event_type TEXT NOT NULL,
  bcs BLOB NOT NULL,
  kind TEXT NOT NULL,
  gate_id TEXT,
  commission_mist INTEGER,
  UNIQUE (tx_digest, event_index)
) STRICT;
CREATE INDEX IF NOT EXISTS events_stream ON events (stream, id);
CREATE INDEX IF NOT EXISTS events_gate ON events (stream, gate_id, id);
CREATE INDEX IF NOT EXISTS events_kind ON events (stream, kind, id);
CREATE TABLE IF NOT EXISTS stream_stats (
  stream TEXT PRIMARY KEY,
  from_checkpoint INTEGER,
  latest_checkpoint INTEGER,
  events INTEGER NOT NULL DEFAULT 0,
  undecodable INTEGER NOT NULL DEFAULT 0,
  gaps INTEGER NOT NULL DEFAULT 0
) STRICT;
CREATE TABLE IF NOT EXISTS gate_stats (
  gate_id TEXT NOT NULL,
  kind TEXT NOT NULL,
  n INTEGER NOT NULL,
  PRIMARY KEY (gate_id, kind)
) STRICT;
CREATE TABLE IF NOT EXISTS gate_commission (gate_id TEXT PRIMARY KEY, total TEXT NOT NULL) STRICT;
";

/// `(id, stream, fixture)` of the rows, in id order. Ids have gaps (4 → 5 is kept, 10 and 11 are missing).
fn rows() -> Vec<(i64, &'static str, Fixture)> {
    let with = |mut f: Fixture, digest: &str| {
        f.transaction_digest = digest.to_owned();
        f
    };
    vec![
        (1, "access-gate", with(minted(&gate_a(), 11, 2000), "fx01")),
        (2, "access-gate", with(consumed(&gate_a(), 12), "fx02")),
        (3, "sealed-content", with(sealed(&gate_a(), 13, "one"), "fx03")),
        (4, "access-gate", with(minted(&gate_b(), 14, 5000), "fx04")),
        (5, "access-gate", with(platform_updated(15), "fx05")),
        (6, "sealed-content", with(sealed(&gate_b(), 16, "other"), "fx06")),
        (7, "access-gate", with(minted(&gate_a(), 17, 1 << 60), "fx07")),
        (8, "access-gate", with(consumed(&gate_b(), 18), "fx08")),
        (9, "sealed-content", with(sealed(&gate_a(), 19, "two"), "fx09")),
        (12, "access-gate", with(minted(&gate_a(), 20, 7), "fx12")),
    ]
}

/// What [`build`] wrote, for assertions.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Built {
    pub events: usize,
    pub max_id: i64,
    pub commission_total: u128,
}

/// Create the SQLite index at `path` (which must not exist) the way the 0.0.13 writer left it: WAL mode,
/// counters exact for the rows, heartbeats and the schema-writer mark present.
pub fn build(path: &Path) -> Built {
    let c = Connection::open(path).expect("create the SQLite fixture");
    c.execute_batch("PRAGMA journal_mode = WAL;").expect("wal");
    c.execute_batch(OLD_SCHEMA).expect("the 0.0.13 schema");
    let rows = rows();
    let mut insert = c
        .prepare(
            "INSERT INTO events (id, stream, tx_digest, event_index, checkpoint, sender, event_type, bcs, kind, gate_id, commission_mist)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
        )
        .expect("prepare");
    for (id, stream, f) in &rows {
        let e = f.indexed();
        insert
            .execute(params![
                id,
                stream,
                e.tx_digest,
                e.event_index,
                e.checkpoint.map(|c| c as i64),
                e.sender,
                e.event_type,
                e.bcs,
                e.kind,
                e.gate_id,
                e.commission_mist
            ])
            .expect("insert");
    }
    drop(insert);
    // Counters, as the writer's ingest transaction kept them (undecodable and gaps as an operator saw
    // them once: two skipped events, one gap).
    c.execute_batch(
        "INSERT INTO stream_stats (stream, from_checkpoint, latest_checkpoint, events, undecodable, gaps)
           SELECT stream, MIN(checkpoint), MAX(checkpoint), COUNT(*), 0, 0 FROM events GROUP BY stream;
         UPDATE stream_stats SET undecodable = 2, gaps = 1 WHERE stream = 'access-gate';
         INSERT INTO gate_stats (gate_id, kind, n)
           SELECT gate_id, kind, COUNT(*) FROM events WHERE stream = 'access-gate' AND gate_id IS NOT NULL GROUP BY gate_id, kind;",
    )
    .expect("counters");
    let mut commission: Vec<(String, u128)> = Vec::new();
    for (_, stream, f) in &rows {
        if let (&"access-gate", Some(g), Some(cm)) = (stream, &f.gate_id, f.commission_mist) {
            match commission.iter_mut().find(|(k, _)| k == g) {
                Some((_, t)) => *t += cm as u128,
                None => commission.push((g.clone(), cm as u128)),
            }
        }
    }
    for (g, total) in &commission {
        c.execute("INSERT INTO gate_commission (gate_id, total) VALUES (?, ?)", params![g, total.to_string()])
            .expect("commission");
    }
    for (k, v) in [
        ("generation", GENERATION.to_owned()),
        ("package:access-gate", ag()),
        ("package:sealed-content", seal()),
        ("stats:v2", "1".to_owned()),
        ("schema_writer", "rust".to_owned()),
        (
            "gap:access-gate",
            r#"{"at":"2026-10-08T09:00:00.000Z","reason":"requested data below earliest available"}"#.to_owned(),
        ),
        (
            "poll:access-gate",
            r#"{"lastSuccessAt":1760000000000,"lastError":null,"lastAttemptAt":1760000000000}"#.to_owned(),
        ),
        (
            "poll:sealed-content",
            r#"{"lastSuccessAt":1760000000000,"lastError":null,"lastAttemptAt":1760000000000}"#.to_owned(),
        ),
        ("ingest:alive", "1760000000000".to_owned()),
    ] {
        c.execute("INSERT INTO meta (key, value) VALUES (?, ?)", params![k, v]).expect("meta");
    }
    c.execute("INSERT INTO cursors (stream, cursor) VALUES ('access-gate', 'Yw=='), ('sealed-content', 'cw==')", [])
        .expect("cursors");
    Built {
        events: rows.len(),
        max_id: rows.iter().map(|(id, _, _)| *id).max().unwrap_or(0),
        commission_total: commission.iter().map(|(_, t)| *t).sum(),
    }
}
